const MINE = ["CHATBOT ONLINE LLC","ChatGPT","Claude","DeepSeek","Gemini","Grok","Norton","OpenAI","Premium","PRO","use.ai","bank statement","billing period","chat","checkout","clipboard","contact","conversation","copy","create","credentials","feature","file","free trial","image style","model","payment method","project","prompt","receipt","refund","rename","send","start chatting","support","trial"];
const norm = (s) => String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');
const MINESET = new Set(MINE.map(norm));
const seen = new Set();
const all = [];
const pages = [];
for (const nm of ['Page A', 'Page B']) {
  let arr = [];
  try { arr = $(nm).all(); } catch (e) { pages.push(nm + ': unavailable'); continue; }
  for (const it of arr) {
    const j = it.json || {};
    const terms = Array.isArray(j.data) ? j.data : [];
    const m = j.meta || {};
    pages.push(nm + ': ' + terms.length + ' items, hasMore=' + m.hasMore);
    for (const t of terms) if (t && t.id && !seen.has(t.id)) { seen.add(t.id); all.push(t); }
  }
}
const groups = new Map();
for (const t of all) {
  const n = norm(t.term);
  if (!MINESET.has(n)) continue;
  if (!groups.has(n)) groups.set(n, []);
  groups.get(n).push({ id: t.id, term: t.term, tags: (t.tags || []).join('/') });
}
const deleteIds = [];
const plan = [];
const singles = [];
for (const [n, list] of groups) {
  list.sort((a, b) => a.id - b.id);
  if (list.length > 1) {
    const keep = list[0];
    const drop = list.slice(1);
    for (const d of drop) deleteIds.push(d.id);
    plan.push(n + ': keep ' + keep.id + ' [' + (keep.tags || 'untagged') + '], delete ' + drop.map(d => d.id).join(','));
  } else {
    singles.push(n + ': 1 copy (' + list[0].id + ')');
  }
}
return [{ json: { pages: pages, total_fetched: all.length, my_terms_found: groups.size, duplicate_groups: plan.length, already_clean: singles.length, delete_count: deleteIds.length, delete_ids: deleteIds, plan: plan, singles: singles } }];

